import { MockLLMProvider } from "../src/llm/mockProvider";
import { GitHubModelsProvider, resolveLLMProviderFromEnv } from "../src/llm/githubModelsProvider";

describe("MockLLMProvider", () => {
  it("deterministically echoes the signature line from the prompt", async () => {
    const provider = new MockLLMProvider();
    const result = await provider.generate("Current signature: add(a: number, b: number): number\nOther context");
    expect(result).toBe(
      "Updated documentation for add(a: number, b: number): number. (generated by mock provider — review before accepting)"
    );
  });
});

describe("resolveLLMProviderFromEnv", () => {
  it("returns undefined when no token is configured", () => {
    expect(resolveLLMProviderFromEnv({})).toBeUndefined();
  });

  it("returns a GitHubModelsProvider when a token is configured", () => {
    const provider = resolveLLMProviderFromEnv({ GITHUB_MODELS_TOKEN: "fake-token" } as NodeJS.ProcessEnv);
    expect(provider).toBeInstanceOf(GitHubModelsProvider);
    expect(provider?.name).toBe("github-models");
  });
});

describe("GitHubModelsProvider", () => {
  const originalFetch = global.fetch;

  afterEach(() => {
    global.fetch = originalFetch;
    jest.restoreAllMocks();
  });

  it("returns the generated content on a successful call", async () => {
    global.fetch = jest.fn().mockResolvedValue({
      ok: true,
      status: 200,
      json: async () => ({ choices: [{ message: { content: "Updated docs." } }] })
    }) as unknown as typeof fetch;

    const provider = new GitHubModelsProvider({ token: "fake-token" });
    const result = await provider.generate("prompt");
    expect(result).toBe("Updated docs.");
  });

  it("retries on a 500 response and succeeds on the next attempt", async () => {
    global.fetch = jest
      .fn()
      .mockResolvedValueOnce({ ok: false, status: 500, text: async () => "server error" })
      .mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => ({ choices: [{ message: { content: "Recovered." } }] })
      }) as unknown as typeof fetch;

    const provider = new GitHubModelsProvider({ token: "fake-token", maxRetries: 2 });
    const result = await provider.generate("prompt");
    expect(result).toBe("Recovered.");
    expect(global.fetch).toHaveBeenCalledTimes(2);
  });

  it("throws after exhausting retries", async () => {
    global.fetch = jest.fn().mockResolvedValue({ ok: false, status: 503, text: async () => "unavailable" }) as unknown as typeof fetch;

    const provider = new GitHubModelsProvider({ token: "fake-token", maxRetries: 1 });
    await expect(provider.generate("prompt")).rejects.toThrow();
    expect(global.fetch).toHaveBeenCalledTimes(2);
  });
});
